export const exportarCSV = "                    ExportarCSV(clipboard=false) {\n                        const rows = document.querySelectorAll(\"table tr\");\n                        let csv = [];\n\n                        for(let i = 0; i < rows.length; i++){\n                            let row = [], cols = rows[i].querySelectorAll(\"td, th\");\n                            for(let j = 0; j < cols.length; j++){\n                                let cellValue = cols[j].innerText;\n                                // Reemplazar caracteres que rompan la secuencia csv\n                                if (cellValue.includes('\"')) { cellValue = cellValue.replaceAll('\"',\"&quot;\") }\n                                if (cellValue.includes(\"'\")) { cellValue = cellValue.replaceAll(\"'\",\"&apos;\") }\n                                if (cellValue.includes(\",\")) { cellValue = '\"' + cellValue + '\"'; }\n                                \n                                row.push(cellValue);\n                            }\n                            csv.push(row.join(\",\"));\n                        }\n                        \n                        const editables = document.querySelectorAll(\"edit-table\");\n                        for(let i = 0; i < editables.length; i++){\n                            const table = editables[i];\n                            let titles = [];\n                            let fields = [];\n\n                            table.Columns.forEach(c => {\n                                if (![\"hide-on-print\",\"no-print\"].includes(c.class)) {\n                                    titles.push(c.title);\n                                    fields.push(c.field);\n                                }\n                            });\n\n                            csv.push(titles.join(\",\"));\n                            for(let j = 0; j < table.DataArray.length; j++){\n                                let item = table.DataArray[j];\n                                let row = [];\n                                fields.forEach(f => {\n                                    let cellValue = item[f]?.toString() ?? \"\";\n                                    // Reemplazar caracteres que rompan la secuencia csv\n                                    if (cellValue.includes('\"')) { cellValue = cellValue.replaceAll('\"',\"&quot;\") }\n                                    if (cellValue.includes(\"'\")) { cellValue = cellValue.replaceAll(\"'\",\"&apos;\") }\n                                    if (cellValue.includes(\",\")) { cellValue = '\"' + cellValue + '\"'; }\n                                    \n                                    row.push(cellValue);\n                                });\n                                csv.push(row.join(\",\"));\n                            }\n                        }\n                        \n                        if (clipboard) {\n                            // Copiar datos csv al portapapeles\n                            navigator.clipboard.writeText(csv.join(\"\\n\"))\n                            .then(() => { alert(\"Se copió al portapapeles.\") })\n                            .catch(() => { alert(\"Error al copiar.\") });\n                        }\n                        else {\n                            // Descargar archivo .csv\n                            let blob = new Blob([new Uint8Array([0xEF, 0xBB, 0xBF]), csv.join(\"\\n\")], {type: \"text/csv;charset=utf-8;\"});\n                            this.SaveBlob(blob,this.titleView+\".csv\");\n                        }\n}";

export const getPrintableHTML = "function getPrintableHTML()\n{\n    const container = document.createElement(\"div\");\n    container.setAttribute(\"data-print-mode\",1);\n\n    container.innerHTML = `\n    <!-- link href=\"https://cdn.jsdelivr.net/npm/bootstrap@5.0.1/dist/css/bootstrap.min.css\" rel=\"stylesheet\" integrity=\"sha384-+0n0xVW2eSR5OomGNYDnhzAbDsOXxcvSN1TPprVMTNDbiYZCxYbOOl7+AMvyTG2x\" crossorigin=\"anonymous\" -->\n    <style>\n        table { width:100%; margin-bottom:1rem; caption-side:bottom; border-collapse:collapse; color:#212529; border-color:#dee2e6; }\n        table>:not(caption)>* { border-width: 1px 0; }\n        table>:not(caption)>*>* { border-width: 0 1px; padding: .25rem .25rem; }\n        tr th { background-color:#DCDCDC; text-align:center; font-size:.9rem; font-weight:500; outline:none; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; -o-text-overflow:ellipsis; }\n        tr th > .sizable-border { height:unset!important; }\n        tr td { background-color:#FFFFFF; color:#000000; font-size:.8rem; }\n        \n        /* .bg-light-gray { background-color: #DCDCDC !important; }\n        .bg-yellow { background-color: #ffe484 !important; }\n        .fw-500 { font-weight: 500 !important; } */\n    </style>\n    `;\n\n    document.querySelectorAll(\".printable-element\").forEach(el => \n    {\n        if (el.tagName===\"EDIT-TABLE\" )\n        {\n            let div=document.createElement(\"div\");\n            div.style.cssText=\"display:flex;width:auto;min-width:100%;overflow: auto;\";\n            div.appendChild(el._shadow.getElementById(el.id).cloneNode(true));\n            container.appendChild(div);\n        }\n        else if(el.tagName===\"TABLE\")\n        {\n            let div=document.createElement(\"div\");\n            div.style.cssText=\"display:flex;width:auto;min-width:100%;overflow: auto;\";\n            div.appendChild(el);\n            container.appendChild(div);\n        }\n        else container.appendChild(el.cloneNode(true));\n    });\n    // Array.prototype.forEach.call(container.querySelectorAll(\"*\"), function(element){\n    //     element.removeAttribute('style');\n    // });\n    return container;\n}";

export const getCurrentContext = "                function getCurrentContext()\n                {\n                    const table = document.getElementById(\"#<table_id>\");\n                    const id = (table?.DataArray[table.CurrentRowIndex()]?.sys_pk ?? \"\");\n                    return { item_id:id, context: {} }\n                }";

